"""Level Factory 0.225.0: every one of the walker's five times of day names a Lux preset (the factory's roadmap 217).

`_preset_for` named night, evening and afternoon; morning, noon and "midnight" fell through to Gas Station
Fluorescent, an interior look. Lux 0.79.0 draws Delco Morning and Delco High Noon.

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * apps/cli/commands/__init__.py -- `_preset_for`: morning, noon (and high noon, midday), midnight.
  * tests/unit/test_time_of_day_presets.py (new) -- the five, the spellings, rain and the fall-through, and every
    name held to Lux's presets; four fail on 0.224.0.
  * tests/unit/test_lux_rain.py -- the morning row holds Delco Morning.
  * VERSION 0.224.0 -> 0.225.0, CHANGELOG.

Generated by `patches/lf_time_of_day/gen_lf_time_of_day.py` from a proven clone; its dry runs, the prove run and the
suite are beside it.

    python patches/patch_lf_time_of_day.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
LF = ROOT / "level_factory"
PINS = {'apps/cli/commands/__init__.py': '7ef4aaf0b0dfc51d', 'tests/unit/test_lux_rain.py': '64f6e0fdd9282bcc'}
EDITS = {'apps/cli/commands/__init__.py': [('lines 1399-1399', '    # Blue Hour / Heavy Rain / Mission Goes Hot.\n', '    # Blue Hour / Heavy Rain / Mission Goes Hot / Delco Night, and since\n    # Lux 0.79.0 Delco Morning / Delco High Noon\n    # (`tests/unit/test_time_of_day_presets.py` reads the names off Lux).\n'), ('lines 1419-1419', '    if tod == "night":\n', '    # THE WALKER\'S FIVE TIMES (2026-10-07): morning, high noon, afternoon,\n    # evening, midnight. Three had a preset, so a brief asking for morning or\n    # noon got Gas Station Fluorescent, an interior look, and one saying\n    # "midnight" -- the walker\'s own word for the night slot -- did too. Lux\n    # 0.79.0 adds the two days (the walker\'s look review, 2026-10-19: "Build\n    # both"); 0.225.0 names all five.\n    if tod in ("night", "midnight"):\n'), ('lines 1424-1425', '        return "Delco Summer Afternoon"\n    return "Gas Station Fluorescent"\n', '        return "Delco Summer Afternoon"\n    if tod == "morning":\n        return "Delco Morning"\n    if tod in ("noon", "high noon", "high_noon", "midday"):\n        return "Delco High Noon"\n    return "Gas Station Fluorescent"\n')], 'tests/unit/test_lux_rain.py': [('lines 53-53', '    ("morning", "Gas Station Fluorescent"),\n', '    # `morning` fell through to Gas Station Fluorescent, an interior look,\n    # until 0.225.0; it asks for Lux 0.79.0\'s `Delco Morning` since\n    # (`tests/unit/test_time_of_day_presets.py` holds all five times).\n    ("morning", "Delco Morning"),\n')]}
NEW_FILES = {'tests/unit/test_time_of_day_presets.py': '"""Every one of the walker\'s five times of day names a Lux preset of its own (0.225.0, the factory\'s roadmap 217).\n\nThe walker, 2026-10-07: a level is set at morning, high noon, afternoon, evening or midnight. `_preset_for` named three,\nand morning, noon and "midnight" fell through to Gas Station Fluorescent, an interior look. Lux 0.79.0 draws the\nmorning and the high noon. A name Lux does not register makes `blend_to_preset` a silent no-op, so the names are held\nto the ones Lux\'s preset folder carries, read off the sibling repo where `tests.siblings` finds one.\n\nFAILS ON 0.224.0: morning, noon and midnight return Gas Station Fluorescent.\n"""\nfrom __future__ import annotations\n\nimport re\nimport sys\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport pytest\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(ROOT))\n\nfrom apps.cli.commands import _preset_for  # noqa: E402\nfrom tests.siblings import not_found, sibling_repo  # noqa: E402\n\n_PRESETS_REL = "addons/lux/presets"\n\nFIVE = {"morning": "Delco Morning", "noon": "Delco High Noon", "afternoon": "Delco Summer Afternoon",\n        "evening": "Blue Hour", "midnight": "Delco Night"}\n\n\ndef _brief(tod, weather="clear"):\n    return SimpleNamespace(time_of_day=tod, weather=weather)\n\n\n@pytest.mark.parametrize("tod,preset", sorted(FIVE.items()))\ndef test_each_of_the_five_times_names_its_own_preset(tod, preset):\n    assert _preset_for(_brief(tod)) == preset\n\n\ndef test_the_spellings_a_brief_uses_today_still_name_theirs():\n    assert _preset_for(_brief("night")) == "Delco Night"\n    assert _preset_for(_brief("NIGHT")) == "Delco Night"\n    for noon in ("high noon", "high_noon", "midday"):\n        assert _preset_for(_brief(noon)) == "Delco High Noon"\n\n\ndef test_rain_still_wins_and_an_unknown_time_still_falls_through():\n    assert _preset_for(_brief("morning", "rain")) == "Heavy Rain"\n    assert _preset_for(_brief("dawn")) == "Gas Station Fluorescent"\n\n\ndef test_every_name_it_returns_is_a_preset_lux_registers():\n    lux = sibling_repo("lux", marker=_PRESETS_REL)\n    if lux is None:\n        pytest.skip(not_found("lux", marker=_PRESETS_REL))\n    names = set()\n    for f in (lux / _PRESETS_REL).glob("*.tres"):\n        m = re.search(r\'^preset_name = &"([^"]+)"\', f.read_text(encoding="utf-8"), re.M)\n        if m:\n            names.add(m.group(1))\n    returned = {_preset_for(_brief(t)) for t in list(FIVE) + ["dawn"]} | {_preset_for(_brief("x", "rain"))}\n    assert returned <= names, sorted(returned - names)\n'}
CHANGELOG = '## [0.225.0] - every one of the walker\'s five times of day names a Lux preset of its own\n\n**The factory\'s roadmap 217.** The walker, 2026-10-07: a level is set at morning, high noon, afternoon, evening or\nmidnight. `_preset_for` named three of them. A brief asking for morning or noon, or saying "midnight" -- the\nwalker\'s own word for the night slot -- fell through to Gas Station Fluorescent, an interior look. Lux 0.79.0 draws\nthe morning and the high noon (the walker\'s look review, 2026-10-19: "Build both").\n\n### Changed\n- `apps/cli/commands._preset_for`: `morning` asks for Delco Morning; `noon`, `high noon`, `high_noon` and `midday`\n  ask for Delco High Noon; `midnight` asks for Delco Night, beside `night`. Rain still wins, and any other word still\n  falls through to Gas Station Fluorescent. The briefs written so far say night, evening or afternoon, and each\n  still names what it did.\n\n### Tests\n- `tests/unit/test_time_of_day_presets.py`: each of the five times names its own preset; the spellings in use still\n  name theirs; rain wins and an unknown word falls through. The last test reads Lux\'s preset folder from the\n  factory\'s sibling `lux/` and holds every name `_preset_for` can return to one Lux registers, since a name Lux\n  lacks makes `blend_to_preset` a silent no-op. It finds Lux through `tests.siblings.sibling_repo`, and skips where\n  there is none (the suite\'s own `test_sibling_locator` refused the first draft, which counted parents). Four fail on\n  0.224.0.\n- `tests/unit/test_lux_rain.py`: its clear-weather row for `morning` held the old fall-through, Gas Station\n  Fluorescent; it holds Delco Morning.\n\n'
OLD_VERSION, NEW_VERSION = '0.224.0', '0.225.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
